<?php require_once __DIR__ . '/../app/bootstrap.php'; use App\Middleware\AuthMiddleware; use App\Services\Database; AuthMiddleware::requireRole('admin'); $q=Database::connection()->query('SELECT c.title,u.name,r.status,r.created_at FROM class_registrations r JOIN users u ON u.id=r.user_id JOIN classes c ON c.id=r.class_id ORDER BY r.created_at DESC'); $rows=$q->fetchAll(); ?>
<!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-[#F5E9DA] p-6"><div class="bg-white rounded shadow p-4"><h1 class="text-2xl mb-3">Registrations</h1><?php foreach($rows as $r):?><div class="border-b py-2"><?=htmlspecialchars($r['name'])?> | <?=htmlspecialchars($r['title'])?> | <span class="text-[#A67C00]"><?=htmlspecialchars($r['status'])?></span></div><?php endforeach;?></div></body></html>
